// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.io.IOException;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

/**
 * Small NONE transactions, such as one statement each, pay per-transaction costs only: no hand-off to the native writer
 * thread, and no dictionary commit when every value already exists.
 */
class LmdbSmallNoneTransactionTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:small:p");
	/** Short literals are inlined in their ID and never reach the dictionary; this one cannot be. */
	private static final String LONG_LITERAL = "a literal far too long to be inlined in a value ID";

	@TempDir
	File directory;

	@Test
	@Timeout(60)
	void aSmallNoneTransactionWritesItsTriplesOnTheCallerThread() throws Exception {
		ThreadRecordingStore sail = new ThreadRecordingStore(directory, config());
		sail.init();
		try {
			try (LmdbStoreConnection seed = (LmdbStoreConnection) sail.getConnection()) {
				seed.begin(IsolationLevels.READ_COMMITTED);
				seed.addStatement(VF.createIRI("urn:small:seed"), P, VF.createLiteral("seed"));
				seed.commit();
			}
			sail.triples.writerThreads.clear();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				writer.addStatement(VF.createIRI("urn:small:s"), P, VF.createLiteral("one"));
				writer.commit();
			}
			assertThat(sail.triples.writerThreads).as("no hand-off to the native writer thread")
					.containsExactly(Thread.currentThread().getName());

			sail.triples.writerThreads.clear();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				for (int i = 0; i < 5_000; i++) {
					writer.addStatement(VF.createIRI("urn:small:bulk/" + i), P, VF.createLiteral("bulk " + i));
				}
				writer.commit();
			}
			assertThat(sail.triples.writerThreads).as("full batches still pipeline through the native writer thread")
					.anyMatch(name -> name.startsWith("LmdbTripleStore-Ingest"));
			try (LmdbStoreConnection reader = (LmdbStoreConnection) sail.getConnection()) {
				assertThat(reader.size()).isEqualTo(5_002);
			}
		} finally {
			sail.shutDown();
		}
	}

	@Test
	@Timeout(60)
	void aNoneTransactionThatOnlyReusesValuesSkipsTheDictionaryCommit() throws Exception {
		LmdbStore sail = new LmdbStore(directory, config());
		sail.init();
		IRI subject = VF.createIRI("urn:small:s");
		try {
			try (LmdbStoreConnection seed = (LmdbStoreConnection) sail.getConnection()) {
				seed.begin(IsolationLevels.READ_COMMITTED);
				seed.addStatement(subject, P, VF.createLiteral("a"));
				seed.addStatement(subject, P, VF.createLiteral("b"));
				seed.commit();
			}
			// Post-ready maintenance and index rebuilds commit the dictionary in the background; they must not count.
			LmdbGcTestMaintenance.awaitPostReady(sail);
			assertThat(sail.awaitIndexRebuild(30L, TimeUnit.SECONDS)).as(sail.getStartupStatus().toString()).isTrue();
			LmdbSailStore backing = sail.getBackingStore();
			long dictionaryTransaction = backing.valueStoreTransactionId();
			long tripleTransaction = backing.tripleStoreTransactionId();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				// A new statement made only of values the dictionary already holds.
				writer.addStatement(VF.createIRI("urn:small:s"), P, VF.createLiteral("a"), VF.createIRI("urn:small:b"));
				writer.commit();
			}
			assertThat(backing.tripleStoreTransactionId()).as("the statement itself is committed")
					.isGreaterThan(tripleTransaction);
			// urn:small:b is new, so this first transaction must commit the dictionary.
			assertThat(backing.valueStoreTransactionId()).isGreaterThan(dictionaryTransaction);

			dictionaryTransaction = backing.valueStoreTransactionId();
			tripleTransaction = backing.tripleStoreTransactionId();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				writer.addStatement(subject, P, VF.createLiteral("b"), VF.createIRI("urn:small:b"));
				writer.commit();
			}
			assertThat(backing.tripleStoreTransactionId()).isGreaterThan(tripleTransaction);
			assertThat(backing.valueStoreTransactionId()).as("no value was created, so nothing was committed")
					.isEqualTo(dictionaryTransaction);

			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				writer.addStatement(subject, P, VF.createLiteral(LONG_LITERAL));
				writer.commit();
			}
			assertThat(backing.valueStoreTransactionId()).as("a new value commits the dictionary")
					.isGreaterThan(dictionaryTransaction);
		} finally {
			sail.shutDown();
		}
		LmdbStore reopened = new LmdbStore(directory, config());
		reopened.init();
		try (LmdbStoreConnection reader = (LmdbStoreConnection) reopened.getConnection()) {
			assertThat(reader.size()).isEqualTo(5);
			try (var statements = reader.getStatements(null, null, VF.createLiteral(LONG_LITERAL), false)) {
				assertThat(statements.stream().count()).isEqualTo(1);
			}
			try (var statements = reader.getStatements(subject, P, null, false, VF.createIRI("urn:small:b"))) {
				assertThat(statements.stream().count()).as("both NONE transactions wrote into this context")
						.isEqualTo(2);
			}
		} finally {
			reopened.shutDown();
		}
	}

	@Test
	@Timeout(60)
	void freshValuesWithLowOrdinalsAreCommittedEvenWhenTheNextIdDoesNotMove() throws Exception {
		LmdbStore sail = new LmdbStore(directory, config());
		sail.init();
		try {
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				IRI subject = VF.createIRI("urn:small:s");
				// Many IRIs first: the fresh session's IRI ordinals push the shared next ID well past the literals'.
				for (int i = 0; i < 300; i++) {
					writer.addStatement(subject, P, VF.createIRI("urn:small:object/" + i));
				}
				writer.flush();
				// Only new literals: each takes a low literal ordinal, so the next ID does not change.
				for (int i = 0; i < 20; i++) {
					writer.addStatement(subject, P, VF.createLiteral(LONG_LITERAL + " " + i));
				}
				writer.flush();
				writer.commit();
			}
		} finally {
			sail.shutDown();
		}
		LmdbStore reopened = new LmdbStore(directory, config());
		reopened.init();
		try (LmdbStoreConnection reader = (LmdbStoreConnection) reopened.getConnection()) {
			try (var statements = reader.getStatements(null, P, null, false)) {
				assertThat(statements.stream().map(statement -> statement.getObject().stringValue()).count())
						.as("every value of the second chunk resolves")
						.isEqualTo(320);
			}
			for (int i = 0; i < 20; i++) {
				try (var statements = reader.getStatements(null, P, VF.createLiteral(LONG_LITERAL + " " + i),
						false)) {
					assertThat(statements.stream().count()).isEqualTo(1);
				}
			}
		} finally {
			reopened.shutDown();
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc,ospc").setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false)
				.setSketchEstimatorEnabled(false);
	}

	private static final class ThreadRecordingStore extends LmdbStore {
		private ThreadRecordingTripleStore triples;

		private ThreadRecordingStore(File directory, LmdbStoreConfig config) {
			super(directory, config);
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketchEnabled) throws IOException {
			return new LmdbSailStore(directory, properties, config, sketchEnabled, null,
					(tripleDir, storeProperties, settings, values) -> {
						triples = new ThreadRecordingTripleStore(tripleDir, storeProperties, settings, values);
						return triples;
					});
		}
	}

	private static final class ThreadRecordingTripleStore extends TripleStore {
		private final Set<String> writerThreads = ConcurrentHashMap.newKeySet();

		private ThreadRecordingTripleStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				ValueStore values) throws IOException {
			super(directory, properties, config, values);
		}

		@Override
		public boolean storeTriple(long subj, long pred, long obj, long context, boolean explicit)
				throws IOException {
			writerThreads.add(Thread.currentThread().getName());
			return super.storeTriple(subj, pred, obj, context, explicit);
		}

		@Override
		void storeTriplesAligned(long[] subj, long[] pred, long[] obj, long[] context, int count, boolean explicit,
				boolean mayHaveInferred, java.util.function.IntConsumer addedIndexConsumer) throws IOException {
			writerThreads.add(Thread.currentThread().getName());
			super.storeTriplesAligned(subj, pred, obj, context, count, explicit, mayHaveInferred,
					addedIndexConsumer);
		}

		@Override
		public void storeTriplesAligned(long[] subj, long[] pred, long[] obj, long[] context, int count,
				boolean explicit, java.util.function.IntConsumer addedIndexConsumer) throws IOException {
			writerThreads.add(Thread.currentThread().getName());
			super.storeTriplesAligned(subj, pred, obj, context, count, explicit, addedIndexConsumer);
		}
	}
}
